UPDATE subscription SET label = #{o.label}, main_subject_only = #{o.mainSubjectOnly},
  new_names_only = #{o.newNamesOnly}, include_abstract_only = #{o.includeAbstractOnly},
  include_references = #{o.includeReferences},
  filters = COALESCE(#{o.filters, typeHandler=org.catalogueoflife.nametracker.store.type.JsonbStringTypeHandler}, '{}'::jsonb), since_year = #{o.sinceYear}, paused = #{o.paused}
WHERE id = #{o.id} AND user_id = #{o.userId}
